public static <T extends Comparable<T>> T maior(List<T> itens) {
    T maior = itens.get(0);
    for (T item : itens) {
        if (item.compareTo(maior) > 0) maior = item;
    }
    return maior;
}

// Producer extends: só lê números
double soma(List<? extends Number> numeros) {
    return numeros.stream().mapToDouble(Number::doubleValue).sum();
}

// Consumer super: só escreve inteiros
void preencher(List<? super Integer> destino) {
    destino.add(1);
    destino.add(2);
}

